// utils/slug.ts

import slugify from "slugify";

/* -------------------------------------------------------------------------- */
/* Types                                                                      */
/* -------------------------------------------------------------------------- */

export interface CreateSlugOptions {
  /**
   * Returned by `createSlug` when nothing slug-worthy is left.
   * Used as-is (not re-slugified), so pass a URL-safe value.
   * @default "untitled"
   */
  fallback?: string;

  /**
   * Lowercase the slug.
   * @default true
   */
  lower?: boolean;

  /**
   * Custom replacements applied before slugifying (e.g. { "f#": "fsharp" }).
   * Keys are matched case-insensitively and override defaults with the same
   * key (in any casing).
   */
  replacements?: Record<string, string>;

  /**
   * Disable the built-in replacements (c++, c#, .net).
   * @default false
   */
  disableDefaultReplacements?: boolean;

  /**
   * Restrict output to ASCII `[a-z0-9._-]`.
   * When false, letters/digits from any script are kept (e.g. Tamil, Chinese),
   * so such titles don't all collapse into the fallback. Remember to
   * `encodeURIComponent` them when building links by hand.
   * @default false
   */
  ascii?: boolean;

  /**
   * Maximum slug length in characters (use `Infinity` for no limit).
   * Truncation prefers a word boundary.
   * @default 100
   */
  maxLength?: number;
}

/* -------------------------------------------------------------------------- */
/* Constants                                                                  */
/* -------------------------------------------------------------------------- */

const DEFAULT_REPLACEMENTS: Readonly<Record<string, string>> = {
  // Languages whose names are mostly symbols
  "c++": "cpp",
  "c#": "csharp",
  "f#": "fsharp",
  "q#": "qsharp",
  "j#": "jsharp",
  "a*": "a-star",

  // Platforms / files where a leading dot or symbol would be lost
  ".net": "dotnet",
  ".env": "dotenv",

  // Common abbreviations containing a slash
  "i/o": "io",
};

const DEFAULT_MAX_LENGTH = 100;

/** Characters that count as "part of a word" for boundary checks. */
const WORD_CLASS = String.raw`\p{L}\p{M}\p{N}_`;
const ENDS_WITH_WORD_CHAR = new RegExp(`[${WORD_CLASS}]$`, "u");

/** What survives into slugify: letters, marks, digits, whitespace, . _ - */
const REMOVE_UNICODE = /[^\p{L}\p{M}\p{N}\s._-]/gu;
const REMOVE_ASCII = /[^A-Za-z0-9\s._-]/g;

/* -------------------------------------------------------------------------- */
/* Replacements                                                               */
/* -------------------------------------------------------------------------- */

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Lowercases keys, drops empty keys, so merging/matching is case-insensitive. */
function normalizeKeys(input: Readonly<Record<string, string>>): Map<string, string> {
  const map = new Map<string, string>();

  for (const [rawKey, rawValue] of Object.entries(input)) {
    const key = rawKey.trim().toLowerCase();
    if (key) map.set(key, String(rawValue));
  }

  return map;
}

type Replacer = (value: string) => string;

/**
 * Compiles all replacements into ONE regex so that:
 * - replacements are applied in a single pass (no chained re-matching),
 * - replacement text is inserted literally (no `$&` / `$1` interpretation),
 * - longer keys win over shorter ones.
 *
 * Boundary rules:
 * - A key never matches directly after a letter/digit/underscore
 *   ("Disc#" is not "csharp", "ASP.NET" is not "ASP dotnet").
 * - If a key ends in a letter/digit, it must not be followed by one either
 *   (".NETCore" is untouched). Keys ending in symbols ("c++", "c#")
 *   don't need that, so "C++20" -> "cpp 20".
 */
function compileReplacer(replacements: Map<string, string>): Replacer {
  if (replacements.size === 0) return (value) => value;

  const alternatives = [...replacements.keys()]
    .sort((a, b) => b.length - a.length)
    .map((key) => {
      const tail = ENDS_WITH_WORD_CHAR.test(key) ? `(?![${WORD_CLASS}])` : "";
      return `${escapeRegExp(key)}${tail}`;
    });

  const pattern = new RegExp(`(?<![${WORD_CLASS}])(?:${alternatives.join("|")})`, "giu");

  return (value) =>
    value.replace(pattern, (match) => {
      const replacement = replacements.get(match.toLowerCase());
      return replacement === undefined ? match : ` ${replacement} `;
    });
}

const defaultReplacer = compileReplacer(normalizeKeys(DEFAULT_REPLACEMENTS));

function getReplacer(options: CreateSlugOptions): Replacer {
  const { replacements, disableDefaultReplacements = false } = options;
  const hasCustom = !!replacements && Object.keys(replacements).length > 0;

  if (!hasCustom) {
    return disableDefaultReplacements ? (value) => value : defaultReplacer;
  }

  const merged = disableDefaultReplacements
    ? new Map<string, string>()
    : normalizeKeys(DEFAULT_REPLACEMENTS);

  for (const [key, value] of normalizeKeys(replacements)) {
    merged.set(key, value);
  }

  return compileReplacer(merged);
}

/* -------------------------------------------------------------------------- */
/* Cleanup helpers                                                            */
/* -------------------------------------------------------------------------- */

/**
 * Normalizes separators:
 * - a lone "." between characters is kept ("node.js", "v1.2.3"),
 * - any other run of "-" / "." becomes a single "-" ("a..b", "a-.-b"),
 * - leading/trailing separators are removed, so the result can never be
 *   "." or ".." (path traversal) or end with a dot.
 */
function tidy(slug: string): string {
  return slug.replace(/[-.]+/g, (run) => (run === "." ? "." : "-")).replace(/^[-._]+|[-._]+$/g, "");
}

function truncate(slug: string, maxLength: number): string {
  if (!Number.isFinite(maxLength)) return slug;

  const chars = Array.from(slug); // code points, not UTF-16 units
  if (chars.length <= maxLength) return slug;

  let kept = chars.slice(0, maxLength);
  const cutInsideWord = !/[-._]/.test(chars[maxLength]);

  if (cutInsideWord) {
    const lastHyphen = kept.lastIndexOf("-");
    if (lastHyphen > maxLength / 2) kept = kept.slice(0, lastHyphen);
  }

  return tidy(kept.join(""));
}

function resolveMaxLength(value: number | undefined): number {
  if (value === undefined || Number.isNaN(value)) return DEFAULT_MAX_LENGTH;
  if (value === Infinity) return Infinity;
  return Math.max(1, Math.floor(value));
}

/* -------------------------------------------------------------------------- */
/* Core                                                                       */
/* -------------------------------------------------------------------------- */

/** Returns the slug, or "" when nothing usable remains. */
function buildSlug(value: unknown, options: CreateSlugOptions): string {
  const { lower = true, ascii = false } = options;

  const input = String(value ?? "").trim();
  if (!input) return "";

  let text = input
    .normalize("NFKC") // fullwidth chars, ligatures, "…" -> "...", etc.
    .replace(/\p{Cf}/gu, ""); // zero-width / bidi control chars

  text = getReplacer(options)(text);

  text = text
    .replace(/['’‘`]/g, "") // "Node's" -> "Nodes"
    .replace(/&/g, " and ") // "Q&A" -> "Q and A"
    .replace(/[/\\]/g, " ") // "HTML/CSS" -> "HTML CSS"
    .replace(/[^\p{L}\p{M}\p{N}\s._-]+/gu, " "); // other symbols -> separator

  let slug = slugify(text, {
    replacement: "-",
    remove: ascii ? REMOVE_ASCII : REMOVE_UNICODE,
    lower: false,
    trim: true,
  });

  slug = slug.normalize("NFC");
  if (lower) slug = slug.toLowerCase();

  slug = tidy(slug);
  slug = truncate(slug, resolveMaxLength(options.maxLength));

  return slug;
}

/* -------------------------------------------------------------------------- */
/* Public API                                                                 */
/* -------------------------------------------------------------------------- */

/**
 * Creates a URL-safe slug.
 *
 *   Node.js          -> node.js
 *   React Router     -> react-router
 *   HTML/CSS         -> html-css
 *   C++              -> cpp
 *   C++20            -> cpp-20
 *   C# Basics        -> csharp-basics
 *   .NET             -> dotnet
 *   ASP.NET Core     -> asp.net-core
 *   Q&A              -> q-and-a
 *   Crème brûlée     -> creme-brulee
 *   தமிழ்            -> தமிழ்   (use { ascii: true } for ASCII-only output)
 *   ".."             -> untitled
 */
export function createSlug(
  value: string | null | undefined,
  options: CreateSlugOptions = {},
): string {
  const { fallback = "untitled" } = options;
  return buildSlug(value, options) || fallback;
}

/**
 * Creates a URL path from segments. Empty segments, and segments that
 * produce no slug, are skipped (no "untitled" placeholders in paths).
 *
 *   createPathFrom(["Programming", "JavaScript", "Node.js"])
 *   -> "programming/javascript/node.js"
 */
export function createPathFrom(
  segments: ReadonlyArray<string | null | undefined>,
  options: CreateSlugOptions = {},
): string {
  return segments
    .map((segment) => buildSlug(segment, options))
    .filter((slug) => slug.length > 0)
    .join("/");
}

/** Variadic shorthand using default options. */
export function createPath(...segments: Array<string | null | undefined>): string {
  return createPathFrom(segments);
}

/**
 * Creates an absolute route.
 *
 *   createRouteFrom(["Programming", "JavaScript", "Node.js"])
 *   -> "/programming/javascript/node.js"
 */
export function createRouteFrom(
  segments: ReadonlyArray<string | null | undefined>,
  options: CreateSlugOptions = {},
): string {
  const path = createPathFrom(segments, options);
  return path ? `/${path}` : "/";
}

/** Variadic shorthand using default options. */
export function createRoute(...segments: Array<string | null | undefined>): string {
  return createRouteFrom(segments);
}
