import { parseCourseMetadata } from "./metadata";
import type { CourseMetadata } from "./types";

function ensureBaseUrl(value: string): string {
  return value.endsWith("/") ? value : `${value}/`;
}

export function resolveRemoteUrl(base: string, path: string): string {
  if (/^(https?:)?\/\//i.test(path)) {
    return path;
  }

  const isRootRelative = path.startsWith("/");
  const encodedPath = path
    .replace(/^\/+/, "")
    .split("/")
    .map((segment) => encodeURIComponent(segment))
    .join("/");

  const baseUrl = new URL(ensureBaseUrl(base));
  const resolutionBase = isRootRelative ? `${baseUrl.origin}/` : ensureBaseUrl(base);
  return new URL(encodedPath, resolutionBase).toString();
}

export function resolveMetadataUrl(docsUrl: string): string {
  return new URL("meta.json", ensureBaseUrl(docsUrl)).toString();
}

function normalizeRemoteTextUrl(url: string): string {
  if (url.includes("github.com")) {
    return url.replace("github.com", "raw.githubusercontent.com").replace("/blob/", "/");
  }

  return url;
}

export async function fetchCourseMetadata(docsUrl: string): Promise<CourseMetadata> {
  const response = await fetch(resolveMetadataUrl(docsUrl), {
    headers: { Accept: "application/json" },
  });

  if (!response.ok) {
    throw new Error(`Metadata request failed with status ${response.status}.`);
  }

  let payload: unknown;
  try {
    payload = await response.json();
  } catch {
    throw new Error("The remote meta.json response is not valid JSON.");
  }

  return parseCourseMetadata(payload);
}

export async function fetchRemoteText(url: string): Promise<string> {
  const response = await fetch(normalizeRemoteTextUrl(url));

  if (!response.ok) {
    throw new Error(`File request failed with status ${response.status}.`);
  }

  return response.text();
}

export function pushClientPath(path: string) {
  window.history.pushState({}, "", path);
  window.dispatchEvent(new PopStateEvent("popstate"));
}