import type { MetadataRoute } from "next";

import { buildLearningIndex } from "~/features/learning/data/remote-index";
import { SITE_URL } from "~/utils/domain";

/**
 *  robots.txt and sitemap.xml are special Next.js routes. They are not normal like /about
 */

export const dynamic = "force-static";
export const revalidate = false;

const STATIC_ROUTES = [
  "",
  "learn",
  "products",
  "services",
  "work",
  "about",
  "privacy_policy",
  "terms_and_condition",
];

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const sitemap: MetadataRoute.Sitemap = [];

  // Static pages
  STATIC_ROUTES.forEach((route) => {
    sitemap.push({
      url: route ? `${SITE_URL}/${route}` : `${SITE_URL}/`,
    });
  });

  const { sitemapPaths } = await buildLearningIndex();
  sitemapPaths.forEach((route) => {
    sitemap.push({ url: `${SITE_URL}${route}` });
  });

  return sitemap;
}
