import type { CourseMetadata, FolderItem } from "./types";

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((item) => typeof item === "string");
}

function parseFolder(value: unknown): FolderItem | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }

  const candidate = value as Record<string, unknown>;
  if (typeof candidate.name !== "string" || !candidate.name.trim()) {
    return null;
  }

  const folders = candidate.folders;
  const files = candidate.files;

  if (folders !== undefined && (!Array.isArray(folders) || folders.some((item) => !parseFolder(item)))) {
    return null;
  }

  if (files !== undefined && !isStringArray(files)) {
    return null;
  }

  return {
    name: candidate.name,
    folders: folders
      ? (folders.map(parseFolder).filter(Boolean) as FolderItem[])
      : undefined,
    files: files as string[] | undefined,
  };
}

export function parseCourseMetadata(value: unknown): CourseMetadata {
  if (!Array.isArray(value)) {
    throw new Error("Course metadata must be an array.");
  }

  const folders = value.map(parseFolder);
  if (folders.some((folder) => folder === null)) {
    throw new Error("Course metadata contains an invalid folder.");
  }

  return folders as FolderItem[];
}