import mainData from "@main-data";
import type { CourseDataType, CourseType } from "~/model/course_model";
import type { LegacyCourseEntry, MainDataType } from "~/model/main_data_model";
import { createSlug } from "~/utils/slug";

function getCourseMetadata(course: CourseType | LegacyCourseEntry) {
  if ("about" in course) {
    return course.about;
  }

  return course;
}

const COURSE_DATA: CourseDataType = Object.fromEntries(
  Object.entries(mainData as MainDataType).map(([category, value]) => {
    const courses = Array.isArray(value) ? value.map(getCourseMetadata) : Object.values(value);
    return [category, courses];
  }),
) as CourseDataType;

/**
 * category slug -> [categoryName, categoryCourses]
 *
 * Built once here, at module initialization, instead of every caller
 * re-scanning `Object.entries(COURSE_DATA)` with its own `.find()`.
 * The client-side learn route imports this map rather than rescanning
 * `COURSE_DATA` for each browser navigation.
 *
 * Duplicate-key safety: only the first category for a given slug is kept,
 * matching `.find()`'s first-match behavior.
 */
export const CATEGORY_BY_SLUG = new Map<
  string,
  [string, (typeof COURSE_DATA)[keyof typeof COURSE_DATA]]
>();

for (const [name, courses] of Object.entries(COURSE_DATA)) {
  const slug = createSlug(name);
  if (!CATEGORY_BY_SLUG.has(slug)) {
    CATEGORY_BY_SLUG.set(slug, [name, courses]);
  }
}

export default COURSE_DATA;
