import type { CourseType } from "~/model/course_model";
import { createPath } from "~/utils/slug";
import { fetchCourseMetadata } from "../lib/remote";
import { createTopicRoute, listTopics } from "../lib/topic";
import type { CourseMetadata, FolderItem } from "../lib/types";
import COURSE_DATA from "./course-data";

export interface GeneratedSearchEntry {
  id: string;
  category: string;
  name: string;
  topic?: string;
  firstTopic?: string;
  firstTopicPath?: string;
  description?: string;
  link?: string;
  keywords?: string;
  path: string;
}

export interface GeneratedLearningIndex {
  version: 1;
  entries: GeneratedSearchEntry[];
  sitemapPaths: string[];
}

/**
 * Collects folder names only. The `files` lists are deliberately ignored:
 * they hold source file names ("index.mdx", "x.md", anything) that are
 * plumbing, not content, and would pollute the index and "Did you mean".
 */
function collectFolderTerms(folder: FolderItem): string[] {
  return [folder.name, ...(folder.folders?.flatMap(collectFolderTerms) ?? [])];
}

/** Finds the chain of folders from the root down to the first folder matching `isTarget`. */
function findFolderChain(
  folders: FolderItem[],
  isTarget: (folder: FolderItem) => boolean,
): FolderItem[] | null {
  for (const folder of folders) {
    if (isTarget(folder)) return [folder];

    const nested = findFolderChain(folder.folders ?? [], isTarget);
    if (nested) return [folder, ...nested];
  }
  return null;
}

/**
 * Names of the folders a topic sits inside, outermost first. For the topic
 * "HTML Images" this is ["HTML Fundamentals"], so searching a section name
 * finds every topic in it. Matches by identity first, then by name.
 */
function collectAncestorTerms(metadata: CourseMetadata, target: FolderItem): string[] {
  const chain =
    findFolderChain(metadata, (folder) => folder === target) ??
    findFolderChain(metadata, (folder) => folder.name === target.name);

  return chain ? chain.slice(0, -1).map((folder) => folder.name) : [];
}

function toKeywords(terms: string[]): string | undefined {
  const unique = [...new Set(terms.map((term) => term.trim()).filter(Boolean))];
  return unique.length > 0 ? unique.join(" ") : undefined;
}

/** Course-level entry (no topics): course name plus every folder name in the course. */
function collectCourseTerms(course: CourseType, metadata: CourseMetadata): string | undefined {
  return toKeywords([course.name, ...metadata.flatMap(collectFolderTerms)]);
}

/** Topic entry: course name, the folders above the topic, then the topic and its subfolders. */
function collectTopicTerms(
  course: CourseType,
  metadata: CourseMetadata,
  topicFolder: FolderItem,
): string | undefined {
  return toKeywords([
    course.name,
    ...collectAncestorTerms(metadata, topicFolder),
    ...collectFolderTerms(topicFolder),
  ]);
}

function coursePath(category: string, course: CourseType): string {
  return `/learn/${createPath(category, course.name)}`;
}

async function getCourseTopics(course: CourseType) {
  if (!course.docs?.trim()) {
    return null;
  }

  try {
    const metadata = await fetchCourseMetadata(course.docs);
    return { metadata, topics: listTopics(metadata, course) };
  } catch (reason: unknown) {
    const message = reason instanceof Error ? reason.message : "Unknown metadata error";
    console.warn(`Unable to index remote course "${course.name}": ${message}`);
    return null;
  }
}

export async function buildLearningIndex(): Promise<GeneratedLearningIndex> {
  const entries: GeneratedSearchEntry[] = [];
  const sitemapPaths = new Set<string>();

  for (const [category, courses] of Object.entries(COURSE_DATA)) {
    sitemapPaths.add(`/learn/${createPath(category)}`);

    for (const course of courses) {
      const rootPath = coursePath(category, course);

      if (course.link) {
        entries.push({
          id: `${createPath(category, course.name)}:external`,
          category,
          name: course.name,
          description: course.description,
          link: course.link,
          path: course.link,
        });
        continue;
      }

      sitemapPaths.add(rootPath);
      const remoteCourse = await getCourseTopics(course);
      const topics = remoteCourse?.topics ?? [];
      const metadata = remoteCourse?.metadata ?? [];
      const keywords = collectCourseTerms(course, metadata);
      const topicPaths = topics.map((topic) =>
        createTopicRoute("learn", category, course.name, topic),
      );

      if (topics.length === 0) {
        entries.push({
          id: `${createPath(category, course.name)}:course`,
          category,
          name: course.name,
          description: course.description,
          keywords,
          path: rootPath,
        });
        continue;
      }

      const firstTopic = topics[0]?.name;
      const firstTopicPath = topicPaths[0];
      topics.forEach((topic, index) => {
        const topicPath = topicPaths[index];
        sitemapPaths.add(topicPath);

        entries.push({
          id: `${createPath(category, course.name, topic.name)}:${index}`,
          category,
          name: course.name,
          topic: topic.name,
          firstTopic,
          firstTopicPath,
          description: course.description,
          keywords: collectTopicTerms(course, metadata, topic.folder),
          path: topicPath,
        });
      });
    }
  }

  return {
    version: 1,
    entries,
    sitemapPaths: [...sitemapPaths],
  };
}